"""Tests for S1 measurement (T9), on synthetic pages generated by code."""

from __future__ import annotations

from collections.abc import Callable

import pytest

from backend.adapters.fakes import FakeBarcode, FakeOcr
from backend.adapters.imaging.cv import CvImaging
from backend.adapters.storage.tempdir import TmpdirStorage
from backend.core.models import PageMeasurement, PageRaw
from backend.core.pipeline.s1_measure import measure
from backend.settings import Settings
from backend.tests.fixtures.synthetic import pages
from backend.tests.fixtures.synthetic.doubles import MarkerBarcode, MarkerOcr
from backend.tests.fixtures.synthetic.pages import Pixels

MakePage = Callable[[Pixels], PageRaw]


def _measure(
    page: PageRaw,
    settings: Settings,
    storage: TmpdirStorage,
    imaging: CvImaging,
    *,
    ocr: object | None = None,
    barcode: object | None = None,
) -> PageMeasurement:
    return measure(
        page,
        settings=settings,
        ocr=ocr or FakeOcr(),  # type: ignore[arg-type]
        barcode=barcode or FakeBarcode(),  # type: ignore[arg-type]
        imaging=imaging,
        storage=storage,
    )


# ---------------------------------------------------------------- the most important test


def test_clean_page_needs_nothing(
    make_page: MakePage, settings: Settings, storage: TmpdirStorage, imaging: CvImaging
) -> None:
    """A clean page must be left alone: nearly every page flagged would mean thresholds too tight."""
    page = make_page(pages.clean_page())
    result = _measure(
        page,
        settings,
        storage,
        imaging,
        ocr=MarkerOcr(storage),
        barcode=MarkerBarcode(storage),
    )
    assert result.needs == []
    assert result.rotation_deg == 0
    assert result.is_photo is False
    assert abs(result.skew_deg) <= settings.skew_threshold_deg


# ---------------------------------------------------------------- orientation


@pytest.mark.parametrize(("scanned_cw", "expected"), [(90, 270), (180, 180), (270, 90)])
def test_detects_rotation_90_180_270(
    scanned_cw: int,
    expected: int,
    make_page: MakePage,
    settings: Settings,
    storage: TmpdirStorage,
    imaging: CvImaging,
) -> None:
    page = make_page(pages.rotated(pages.clean_page(), scanned_cw))
    result = _measure(
        page, settings, storage, imaging, ocr=MarkerOcr(storage), barcode=MarkerBarcode(storage)
    )
    assert result.rotation_deg == expected
    assert result.needs == ["rotate"]
    assert result.rotation_votes[str(expected)] == 2  # barcode and OSD agree


def test_text_vote_runs_only_when_barcode_and_osd_disagree(
    make_page: MakePage, settings: Settings, storage: TmpdirStorage, imaging: CvImaging
) -> None:
    page = make_page(pages.rotated(pages.clean_page(), 90))
    ocr = MarkerOcr(storage)
    _measure(page, settings, storage, imaging, ocr=ocr, barcode=MarkerBarcode(storage))
    assert ocr.probes == []  # two signals agreed, so the four-pass OCR probe was skipped


def test_text_vote_breaks_a_barcode_osd_disagreement(
    make_page: MakePage, settings: Settings, storage: TmpdirStorage, imaging: CvImaging
) -> None:
    # A sideways sticker on an upright page: the barcode says 90, OSD abstains, the text
    # probe finds Hebrew words only at 0 degrees. Barcode alone must not rotate the page.
    page = make_page(pages.clean_page())

    class SidewaysSticker(MarkerBarcode):
        def sweep(self, image, orientations=(0, 90, 180, 270)):  # type: ignore[no-untyped-def]
            return [hit.model_copy(update={"orientation_deg": 90}) for hit in super().sweep(image)]

    ocr = MarkerOcr(storage, osd=None)
    result = _measure(page, settings, storage, imaging, ocr=ocr, barcode=SidewaysSticker(storage))
    assert result.rotation_deg == 0
    assert result.rotation_votes == {"0": 1, "90": 1, "180": 0, "270": 0}
    assert len(ocr.probes) == 4


def test_text_and_osd_agree_without_any_barcode(
    make_page: MakePage, settings: Settings, storage: TmpdirStorage, imaging: CvImaging
) -> None:
    # A rotated SAP-style page has no barcode; OSD plus the Hebrew word count carry the vote.
    page = make_page(pages.rotated(pages.clean_page(), 270))
    result = _measure(
        page,
        settings,
        storage,
        imaging,
        ocr=MarkerOcr(storage),
        barcode=MarkerBarcode(storage, present=False),
    )
    assert result.rotation_deg == 90


def test_single_signal_is_not_enough_to_rotate(
    make_page: MakePage, settings: Settings, storage: TmpdirStorage, imaging: CvImaging
) -> None:
    page = make_page(pages.rotated(pages.clean_page(), 90))
    result = _measure(
        page,
        settings,
        storage,
        imaging,
        ocr=MarkerOcr(storage, osd=None, hebrew_words=0),  # OSD abstains, text finds nothing
        barcode=MarkerBarcode(storage),
    )
    assert result.rotation_deg == 0
    assert "rotate" not in result.needs


def test_tie_goes_to_the_barcode_when_one_vote_suffices(
    make_page: MakePage, tmp_path: object, storage: TmpdirStorage, imaging: CvImaging
) -> None:
    lenient = Settings(_env_file=None, data_dir=str(tmp_path), rotation_min_votes=1)  # type: ignore[call-arg]
    page = make_page(pages.rotated(pages.clean_page(), 90))  # truth: needs 270
    result = _measure(
        page,
        lenient,
        storage,
        imaging,
        ocr=MarkerOcr(storage, osd=180, hebrew_words=0),  # 180 vs barcode 270: a tie
        barcode=MarkerBarcode(storage),
    )
    assert result.rotation_deg == 270


def test_tie_without_barcode_means_no_rotation(
    make_page: MakePage, tmp_path: object, storage: TmpdirStorage, imaging: CvImaging
) -> None:
    lenient = Settings(_env_file=None, data_dir=str(tmp_path), rotation_min_votes=1)  # type: ignore[call-arg]
    page = make_page(pages.rotated(pages.clean_page(), 90))
    result = _measure(
        page,
        lenient,
        storage,
        imaging,
        ocr=MarkerOcr(storage, osd=180),  # OSD says 180, the Hebrew word count says 270
        barcode=MarkerBarcode(storage, present=False),
    )
    assert result.rotation_votes == {"0": 0, "90": 0, "180": 1, "270": 1}
    assert result.rotation_deg == 0


# ---------------------------------------------------------------- pixel measurements


@pytest.mark.parametrize("ccw", [1.5, -1.5, 7.0, -7.0])
def test_detects_skew_within_half_degree(
    ccw: float,
    make_page: MakePage,
    settings: Settings,
    storage: TmpdirStorage,
    imaging: CvImaging,
) -> None:
    page = make_page(pages.skewed(pages.clean_page(), ccw))
    result = _measure(page, settings, storage, imaging)
    # Turning the page counter-clockwise lifts the baseline: negative skew by convention.
    assert result.skew_deg == pytest.approx(-ccw, abs=0.5)
    assert "deskew" in result.needs


def test_skew_is_measured_independently_of_orientation(
    make_page: MakePage, settings: Settings, storage: TmpdirStorage, imaging: CvImaging
) -> None:
    page = make_page(pages.skewed(pages.rotated(pages.clean_page(), 90), 2.0))
    assert _measure(page, settings, storage, imaging).skew_deg == pytest.approx(-2.0, abs=0.5)


def test_skew_beyond_the_limit_is_reported_as_zero(
    make_page: MakePage, tmp_path: object, storage: TmpdirStorage, imaging: CvImaging
) -> None:
    strict = Settings(_env_file=None, data_dir=str(tmp_path), skew_max_deg=5.0)  # type: ignore[call-arg]
    page = make_page(pages.skewed(pages.clean_page(), 7.0))
    result = _measure(page, strict, storage, CvImaging(settings=strict))
    assert result.skew_deg == 0.0


def test_fax_fixture_flags_denoise_and_sharpen(
    make_page: MakePage, settings: Settings, storage: TmpdirStorage, imaging: CvImaging
) -> None:
    page = make_page(pages.fax(pages.clean_page()))
    result = _measure(page, settings, storage, imaging)
    assert "denoise" in result.needs
    assert "sharpen" in result.needs
    assert result.blur_score < settings.blur_threshold
    assert result.noise_score > settings.noise_threshold


def test_blurred_page_flags_only_sharpen(
    make_page: MakePage, settings: Settings, storage: TmpdirStorage, imaging: CvImaging
) -> None:
    result = _measure(make_page(pages.blurred(pages.clean_page())), settings, storage, imaging)
    assert result.needs == ["sharpen"]


def test_shadowed_page_flags_clahe(
    make_page: MakePage, settings: Settings, storage: TmpdirStorage, imaging: CvImaging
) -> None:
    result = _measure(make_page(pages.shadowed(pages.clean_page())), settings, storage, imaging)
    assert "clahe" in result.needs
    assert result.illumination_cv > settings.illumination_cv_threshold


def test_photo_fixture_flags_perspective(
    make_page: MakePage, settings: Settings, storage: TmpdirStorage, imaging: CvImaging
) -> None:
    result = _measure(make_page(pages.photographed(pages.clean_page())), settings, storage, imaging)
    assert result.is_photo is True
    assert "perspective" in result.needs


def test_straight_scan_is_not_a_photo(
    make_page: MakePage, settings: Settings, storage: TmpdirStorage, imaging: CvImaging
) -> None:
    # A rotated but rectangular sheet must not be mistaken for perspective distortion.
    page = make_page(pages.skewed(pages.clean_page(), 3.0))
    assert _measure(page, settings, storage, imaging).is_photo is False


# ---------------------------------------------------------------- never raises


def test_missing_image_reports_neutral_values_without_raising(
    make_page: MakePage, settings: Settings, storage: TmpdirStorage, imaging: CvImaging
) -> None:
    page = make_page(pages.clean_page())
    storage.purge_job(page.image.job_id)  # the image is gone
    result = _measure(page, settings, storage, imaging)
    assert result.needs == []
    assert result.rotation_deg == 0
    assert result.skew_deg == 0.0
    assert result.blur_score == settings.blur_threshold  # neutral: sits on the threshold


def test_tiny_one_pixel_image_is_measured_without_raising(
    make_page: MakePage, settings: Settings, storage: TmpdirStorage, imaging: CvImaging
) -> None:
    import numpy as np

    page = make_page(np.full((1, 1, 3), 255, dtype=np.uint8))
    result = _measure(page, settings, storage, imaging)
    assert result.rotation_deg == 0
    assert result.skew_deg == 0.0
